create or replace function private.service_titan_dispatch_feed(p_start timestamptz,p_end timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_result jsonb; begin if not public.has_permission_for_current_user('view_dispatch') then raise exception 'Dispatch permission required'; end if; select coalesce(jsonb_agg(x order by x->'appointment'->>'start'),'[]'::jsonb) into v_result from (select jsonb_build_object('appointment',a.payload,'job',j.payload,'customer',c.payload,'location',l.payload,'assignments',coalesce((select jsonb_agg(jsonb_build_object('assignment',aa.payload,'technician',t.payload)) from public.service_titan_records aa left join public.service_titan_records t on t.resource='technicians' and t.external_id=coalesce(aa.payload->>'technicianId',aa.payload->>'technician_id') where aa.resource='appointment_assignments' and coalesce(aa.payload->>'appointmentId',aa.payload->>'appointment_id')=a.external_id),'[]'::jsonb)) x from public.service_titan_records a left join public.service_titan_records j on j.resource='jobs' and j.external_id=a.payload->>'jobId' left join public.service_titan_records c on c.resource='customers' and c.external_id=coalesce(a.payload->>'customerId',j.payload->>'customerId') left join public.service_titan_records l on l.resource='locations' and l.external_id=j.payload->>'locationId' where a.resource='appointments' and nullif(a.payload->>'start','')::timestamptz>=p_start and nullif(a.payload->>'start','')::timestamptz<p_end order by nullif(a.payload->>'start','')::timestamptz) q; return v_result; end $$;